+import { verifyToken, SignedToken } from "./token.ts";
+
+export interface EdgeValidationResult {
+  valid: boolean;
+  sessionId?: string;
+  userId?: string;
+  reason?: string;
+}
+
+export const validateSessionAtEdge = (
+  token: string,
+  recentRevocations: string[],
+): EdgeValidationResult => {
+  const payload = verifyToken(token);
+
+  if (!payload) {
+    return { valid: false, reason: "invalid_token" };
+  }
+
+  if (recentRevocations.includes(payload.sessionId)) {
+    return { valid: false, reason: "revoked" };
+  }
+
+  return {
+    valid: true,
+    sessionId: payload.sessionId,
+    userId: payload.userId,
+  };
+};
+
+export type { SignedToken };
