+interface RevokedSession {
+  sessionId: string;
+  revokedAt: number;
+}
+
+const REVOCATION_TTL_SECONDS = 120; // Keep revocations for 2 minutes to be safe
+const revocations = new Map<string, number>();
+
+export const markRevoked = (sessionId: string): void => {
+  revocations.set(sessionId, Math.floor(Date.now() / 1000));
+};
+
+export const isRevoked = (sessionId: string): boolean => {
+  const revokedAt = revocations.get(sessionId);
+  if (revokedAt === undefined) return false;
+
+  const now = Math.floor(Date.now() / 1000);
+  if (now - revokedAt > REVOCATION_TTL_SECONDS) {
+    revocations.delete(sessionId);
+    return false;
+  }
+
+  return true;
+};
+
+export const getRecentRevocations = (): RevokedSession[] => {
+  const now = Math.floor(Date.now() / 1000);
+  const recent: RevokedSession[] = [];
+
+  for (const [sessionId, revokedAt] of revocations.entries()) {
+    if (now - revokedAt <= REVOCATION_TTL_SECONDS) {
+      recent.push({ sessionId, revokedAt });
+    } else {
+      revocations.delete(sessionId);
+    }
+  }
+
+  return recent;
+};
