+import crypto from "crypto";
+
+const SECRET_KEY = process.env.SESSION_SECRET_KEY || "dev-key-change-in-prod";
+
+export interface SignedToken {
+  sessionId: string;
+  userId: string;
+  issuedAt: number;
+  expiresAt: number;
+}
+
+export const signToken = (
+  sessionId: string,
+  userId: string,
+  ttlSeconds: number = 3600,
+): string => {
+  const issuedAt = Math.floor(Date.now() / 1000);
+  const expiresAt = issuedAt + ttlSeconds;
+
+  const payload = {
+    sessionId,
+    userId,
+    issuedAt,
+    expiresAt,
+  };
+
+  const payloadStr = JSON.stringify(payload);
+  const signature = crypto
+    .createHmac("sha256", SECRET_KEY)
+    .update(payloadStr)
+    .digest("hex");
+
+  return Buffer.from(payloadStr).toString("base64") +
+    "." +
+    signature;
+};
+
+export const verifyToken = (token: string): SignedToken | null => {
+  try {
+    const [payloadB64, signature] = token.split(".");
+    if (!payloadB64 || !signature) return null;
+
+    const payloadStr = Buffer.from(payloadB64, "base64").toString("utf-8");
+    const expectedSignature = crypto
+      .createHmac("sha256", SECRET_KEY)
+      .update(payloadStr)
+      .digest("hex");
+
+    if (signature !== expectedSignature) return null;
+
+    const payload = JSON.parse(payloadStr) as SignedToken;
+
+    const now = Math.floor(Date.now() / 1000);
+    if (payload.expiresAt < now) return null;
+
+    return payload;
+  } catch {
+    return null;
+  }
+};
